/** Actual named-tag/dye/sample input, native opaque+glass geometry/text/items, reload and true two-chunk return.
 * Proposed fixture18998..19024,z0..16, unload20000. STAGED, UNRUN. No fake display-link/CC/signal framework.
 */
final class NixiePlacardRenderingTest {
    private static final BlockPos N=new BlockPos(19005,6,5),P=N.east(8);
    private static final String SAMPLE="Native placard source sample";
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 19010.0 10.0 10.0");context.waitFor(client->Math.abs(client.player.getX()-19010.0)<.1&&Math.abs(client.player.getZ()-10.0)<.1,300);context.waitFor(client->client.level.isLoaded(P)&&Math.abs(client.player.getX()-19010)<.1,500);server.runCommand("fill 18998 4 0 19024 4 16 minecraft:smooth_quartz");
        for(int i=0;i<4;i++){block(world,N.east(i).below(),"create:metal_girder[axis=x,x=true,z=false]");block(world,N.east(i),"create:nixie_tube[double_face=floor,facing=east,waterlogged=false]");}
        block(world,P.below(),"create:metal_girder");block(world,P,"create:placard[face=floor,facing=north,waterlogged=false,powered=false]");block(world,P.east(),"minecraft:redstone_lamp");block(world,N.east().south(2),"minecraft:smooth_quartz");block(world,P.south(2),"minecraft:smooth_quartz");
        var tag=new ItemStack(Items.NAME_TAG);tag.set(DataComponents.CUSTOM_NAME,Component.literal("CREATE42"));slot(world,0,tag);slot(world,1,new ItemStack(Items.DYE.pick(DyeColor.BLUE),2));var sample=new ItemStack(Items.DIAMOND,3);sample.set(DataComponents.CUSTOM_NAME,Component.literal(SAMPLE));slot(world,2,sample);slot(world,4,ItemStack.EMPTY);
        server.runCommand("gamemode survival @p");server.runCommand("tp @p 19006.5 7 7.5");context.waitFor(client->Math.abs(client.player.getX()-19006.5)<.1&&Math.abs(client.player.getZ()-7.5)<.1,300);context.getInput().pressKey(InputConstants.KEY_1);context.waitFor(client->client.player.getMainHandItem().is(Items.NAME_TAG),200);use(context,N.east(),true);
        waitServer(context,world,level->text(level,N,"C","R")&&text(level,N.east(),"E","A")&&text(level,N.east(2),"T","E")&&text(level,N.east(3),"4","2"),200,"Actual name-tag click did not walk the real complete Nixie row");
        context.getInput().pressKey(InputConstants.KEY_2);context.waitFor(client->client.player.getMainHandItem().is(Items.DYE.pick(DyeColor.BLUE)),150);use(context,N.east(),true);
        waitServer(context,world,level->{for(int i=0;i<4;i++)if(!LoadedLevelAccess.blockState(level,N.east(i)).is(AllBlocks.NIXIE_TUBES.get(DyeColor.BLUE)))return false;return text(level,N,"C","R")&&text(level,N.east(3),"4","2");},200,"Actual dye click lost row text or failed to use source colored blocks");
        context.waitFor(client->client.player.getMainHandItem().getCount()==2,150);verifyNixies(context);world.getConnection().waitForChunksRender();look(context,Vec3.atCenterOf(N.east()).add(0,.1,0));screenshot(context,"create-vulkan-native-nixie-real-nametag-row-and-blue-translucent-glass");
        server.runCommand("tp @p 19013.5 7 7.5");context.waitFor(client->Math.abs(client.player.getX()-19013.5)<.1&&Math.abs(client.player.getZ()-7.5)<.1,300);context.getInput().pressKey(InputConstants.KEY_3);context.waitFor(client->client.player.getMainHandItem().is(Items.DIAMOND),150);use(context,P,false);
        waitServer(context,world,level->placard(level)!=null&&placard(level).getHeldItem().getHoverName().getString().equals(SAMPLE)&&placard(level).getHeldItem().getCount()==1,200,"Actual survival placard sample insertion failed");context.waitFor(client->client.player.getMainHandItem().getCount()==2,150);verifyPlacard(context);
        use(context,P,false);waitServer(context,world,level->LoadedLevelAccess.blockState(level,P).getValue(PlacardBlock.POWERED)&&placard(level).getPoweredTicks()>0&&LoadedLevelAccess.blockState(level,P.east()).getValue(net.minecraft.world.level.block.RedstoneLampBlock.LIT),150,"Actual matching sample did not produce the real source pulse/lamp update");screenshot(context,"create-vulkan-native-placard-real-component-sample-redstone-pulse");
        waitServer(context,world,level->placard(level).getPoweredTicks()==0&&!LoadedLevelAccess.blockState(level,P).getValue(PlacardBlock.POWERED)&&!LoadedLevelAccess.blockState(level,P.east()).getValue(net.minecraft.world.level.block.RedstoneLampBlock.LIT),200,"Real19tick placard pulse failed to finish");
        var oldModel=context.computeOnClient(client->client.getModelManager().getBlockStateModelSet().get(AllBlocks.ORANGE_NIXIE_TUBE.defaultBlockState()));var reload=context.computeOnClient(client->client.reloadResourcePacks());context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);reload.join();context.runOnClient(client->{if(client.getModelManager().getBlockStateModelSet().get(AllBlocks.ORANGE_NIXIE_TUBE.defaultBlockState())==oldModel)throw new AssertionError("Nixie native layered models remained stale after actual reload");});verifyNixies(context);verifyPlacard(context);
        var oldNixie=new AtomicReference<NixieTubeBlockEntity>();var oldPlacard=new AtomicReference<PlacardBlockEntity>();server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();oldNixie.set(nixie(level,N));oldPlacard.set(placard(level));});server.runCommand("gamemode spectator @p");server.runCommand("tp @p 20000 20 20000");
        waitServer(context,world,level->level.getChunkSource().getChunkNow(N.getX()>>4,N.getZ()>>4)==null&&level.getChunkSource().getChunkNow(P.getX()>>4,P.getZ()>>4)==null,800,"Both genuine Nixie/placard fixture chunks failed to unload");
        NativeFixtureChunkUnload.finish(context,world,oldNixie.get(),oldPlacard.get());
        server.runCommand("tp @p 19010.0 10.0 10.0");context.waitFor(client->Math.abs(client.player.getX()-19010.0)<.1&&Math.abs(client.player.getZ()-10.0)<.1,300);waitServer(context,world,level->nixie(level,N)!=null&&nixie(level,N)!=oldNixie.get()&&placard(level)!=null&&placard(level)!=oldPlacard.get()&&text(level,N,"C","R")&&text(level,N.east(3),"4","2")&&placard(level).getHeldItem().getCount()==1&&placard(level).getHeldItem().getHoverName().getString().equals(SAMPLE)&&placard(level).getPoweredTicks()==0,600,"Actual chunk return reset source row/index/color or lost/duplicated held item/pulse");context.waitFor(client->java.util.stream.IntStream.range(0,4).allMatch(i->LoadedLevelAccess.blockEntity(client.level,N.east(i)) instanceof NixieTubeBlockEntity)&&LoadedLevelAccess.blockEntity(client.level,P) instanceof PlacardBlockEntity,300);verifyNixies(context);verifyPlacard(context);world.getConnection().waitForChunksRender();screenshot(context,"create-vulkan-native-nixie-placard-real-data-after-two-chunk-return");
        server.runCommand("gamemode survival @p");server.runCommand("tp @p 19013.5 7 7.5");context.waitFor(client->Math.abs(client.player.getX()-19013.5)<.1&&Math.abs(client.player.getZ()-7.5)<.1,300);context.getInput().pressKey(InputConstants.KEY_5);context.waitFor(client->client.player.getMainHandItem().isEmpty(),150);look(context,Vec3.atCenterOf(P).add(0,-.4,0));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(P),150);context.getInput().pressKey(options->options.keyAttack);
        waitServer(context,world,level->placard(level)!=null&&placard(level).getHeldItem().isEmpty()&&LoadedLevelAccess.blockState(level,P).is(AllBlocks.PLACARD),200,"Actual single attack did not return the held sample while preserving placard");context.waitFor(client->sampleCount(client.player.getInventory())==3,200);
        block(world,N.north(),"minecraft:redstone_block");server.runCommand("tp @p 19006.5 7 7.5");context.waitFor(client->Math.abs(client.player.getX()-19006.5)<.1&&Math.abs(client.player.getZ()-7.5)<.1,300);use(context,N,true);waitServer(context,world,level->text(level,N,"1","5")&&text(level,N.east(),"E","A"),200,"Actual empty-hand clear did not restore only the selected native cell to physical redstone");
    }
    private static void slot(TestSingleplayerContext world,int slot,ItemStack item){world.getServer().runOnServer(ignored->{var player=world.getConnection().getServerLevel().getServer().getPlayerList().getPlayers().getFirst();player.getInventory().setItem(slot,item.copy());player.connection.send(player.getInventory().createInventoryUpdatePacket(slot));});}
    private static int sampleCount(net.minecraft.world.entity.player.Inventory inventory){int count=0;for(int i=0;i<inventory.getContainerSize();i++){var stack=inventory.getItem(i);if(stack.is(Items.DIAMOND)&&stack.getHoverName().getString().equals(SAMPLE))count+=stack.getCount();}return count;}
    private static void verifyNixies(ClientGameTestContext context){context.runOnClient(client->{
        for(int index=0;index<4;index++){
            var pos=N.east(index);var entity=(NixieTubeBlockEntity)LoadedLevelAccess.blockEntity(client.level,pos);var state=(NixieTubeRenderer.State)client.getBlockEntityRenderDispatcher().tryExtractRenderState(entity,.5f,null,false);if(state==null||state.tubes.size()!=2||state.color!=DyeColor.BLUE||state.height!=3||state.yaw!=0||state.roll!=0||state.tubes.stream().anyMatch(tube->tube.front()>>>24!=255))throw new AssertionError("Actual native source Nixie glyph/color/orientation state missing");
            var mesh=Renderer.get().mutableMesh();var block=entity.getBlockState();client.getModelManager().getBlockStateModelSet().get(block).emitQuads(mesh.emitter(),client.level,pos,block,RandomSource.create(42),side->false);int[] layers=new int[2];mesh.forEach(quad->{if(quad.chunkLayer()==net.minecraft.client.renderer.chunk.ChunkSectionLayer.SOLID)layers[0]++;if(quad.chunkLayer()==net.minecraft.client.renderer.chunk.ChunkSectionLayer.TRANSLUCENT)layers[1]++;});if(layers[0]!=12||layers[1]!=10)throw new AssertionError("Source metal/glass composite requires12opaque and10translucent actual native quads");
        }
        for(var block:AllBlocks.NIXIE_TUBES.values())for(var state:block.getStateDefinition().getPossibleStates())if(client.getModelManager().getBlockStateModelSet().get(state)==client.getModelManager().getBlockStateModelSet().missingModel())throw new AssertionError("Missing actual colored Nixie model "+state);
    });}
    private static void verifyPlacard(ClientGameTestContext context){context.runOnClient(client->{var entity=(PlacardBlockEntity)LoadedLevelAccess.blockEntity(client.level,P);var state=(PlacardRenderer.State)client.getBlockEntityRenderDispatcher().tryExtractRenderState(entity,.5f,null,false);if(state==null||state.item.isEmpty()||state.pitch!=90||state.scale!=.375f)throw new AssertionError("Actual native source placard item/orientation/scale missing");for(var block:AllBlocks.PLACARD.getStateDefinition().getPossibleStates())if(client.getModelManager().getBlockStateModelSet().get(block)==client.getModelManager().getBlockStateModelSet().missingModel())throw new AssertionError("Missing native placard state "+block);});}
    private static NixieTubeBlockEntity nixie(ServerLevel level,BlockPos pos){return LoadedLevelAccess.blockEntity(level,pos)instanceof NixieTubeBlockEntity entity?entity:null;}
    private static PlacardBlockEntity placard(ServerLevel level){return LoadedLevelAccess.blockEntity(level,P)instanceof PlacardBlockEntity entity?entity:null;}
    private static boolean text(ServerLevel level,BlockPos pos,String first,String second){var entity=nixie(level,pos);return entity!=null&&entity.getDisplayedStrings().first().equals(first)&&entity.getDisplayedStrings().second().equals(second);}
    private static void use(ClientGameTestContext context,BlockPos pos,boolean tube){look(context,Vec3.atCenterOf(pos).add(tube?-.25:0,tube?.1:-.4,0));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(pos),150);context.waitTicks(6);context.getInput().pressKey(options->options.keyUse);}
    private static void block(TestSingleplayerContext world,BlockPos pos,String state){world.getServer().runCommand("setblock "+pos.getX()+" "+pos.getY()+" "+pos.getZ()+" "+state);}
    private static void screenshot(ClientGameTestContext context,String name){context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot(name);}
    private static void look(ClientGameTestContext context,Vec3 target){var angle=context.computeOnClient(client->{var delta=target.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});context.getInput().lookAt(angle.x,angle.y);}
    private static void waitServer(ClientGameTestContext context,TestSingleplayerContext world,Predicate<ServerLevel> condition,int ticks,String message){var ready=new AtomicBoolean();for(int tick=0;tick<ticks&&!ready.get();tick++){world.getServer().runOnServer(ignored->ready.set(condition.test(world.getConnection().getServerLevel())));if(!ready.get())context.waitTicks(1);}if(!ready.get())throw new AssertionError(message);}
}
